    public void load(ResultSet rs, int id) throws SQLException {
        this.id = id;
        this.code = rs.getString(2);
        this.name = rs.getString(3);
        this.description = rs.getString(4);
        this.image = rs.getString(5);
        this.width = rs.getDouble(6);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_Width, rs.wasNull());
        this.height = rs.getDouble(7);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_Height, rs.wasNull());
        this.depth = rs.getDouble(8);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_Depth, rs.wasNull());
        this.weight = rs.getInt(9);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_Weight, rs.wasNull());
        this.specialOnly = (rs.getShort(10) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_SpecialOnly, rs.wasNull());
        this.location = rs.getString(11);
        this.price = rs.getDouble(12);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_Price, rs.wasNull());
        java.sql.Date date;
        date = rs.getDate(13);
        if (date != null) this.discontinuedDate = new OADate(date);
        this.termCode = rs.getString(14);
        this.isProduced = (rs.getShort(15) == 1);
        OAObjectInfoDelegate.setPrimitiveNull(this, P_IsProduced, rs.wasNull());
        this.qbListId = rs.getString(16);
        java.sql.Timestamp timestamp;
        timestamp = rs.getTimestamp(17);
        if (timestamp != null) this.lastChanged = new OADateTime(timestamp);
        int fileInfoFkey = rs.getInt(18);
        setFkeyProperty(P_FileInfo, rs.wasNull() ? null : fileInfoFkey);
        int imageStoreFkey = rs.getInt(19);
        setFkeyProperty(P_ImageStore, rs.wasNull() ? null : imageStoreFkey);
        int itemCategoryFkey = rs.getInt(20);
        setFkeyProperty(P_ItemCategory, rs.wasNull() ? null : itemCategoryFkey);
        int moldFkey = rs.getInt(21);
        setFkeyProperty(P_Mold, rs.wasNull() ? null : moldFkey);
        int productionAreaFkey = rs.getInt(22);
        setFkeyProperty(P_ProductionArea, rs.wasNull() ? null : productionAreaFkey);

        this.changedFlag = false;
        this.newFlag = false;
    }
